package main

// C-05 names claim.behavior in its failure detail, and the reference writes it
// with %s, which is str(). A Go type assertion that fails yields "", so a null
// behavior was spelled as an empty string -- and when scoring_metrics contains
// an empty string the check stopped failing at all. These tests pin str() for
// every JSON type against Python, and pin that verdict case on its own.
//
// Expectations come from testdata/pystr_vectors.json, generated by
// testdata/make_pystr.py. Regenerate it after a Python upgrade.

import (
	"encoding/json"
	"math"
	"os"
	"strconv"
	"testing"
)

type pystrVectors struct {
	Floats []struct {
		Bits string `json:"bits"`
		Str  string `json:"str"`
	} `json:"floats"`
	Numbers []struct {
		Literal string `json:"literal"`
		Str     string `json:"str"`
	} `json:"numbers"`
	Values []struct {
		JSON string `json:"json"`
		Str  string `json:"str"`
	} `json:"values"`
}

func loadPystrVectors(t *testing.T) pystrVectors {
	t.Helper()
	data, err := os.ReadFile("testdata/pystr_vectors.json")
	if err != nil {
		t.Fatalf("read pystr vectors: %v", err)
	}
	var vectors pystrVectors
	if err := json.Unmarshal(data, &vectors); err != nil {
		t.Fatalf("parse pystr vectors: %v", err)
	}
	if len(vectors.Floats) == 0 || len(vectors.Numbers) == 0 || len(vectors.Values) == 0 {
		t.Fatal("pystr vectors are empty; regenerate with testdata/make_pystr.py")
	}
	return vectors
}

func TestPyFloatReprVectors(t *testing.T) {
	vectors := loadPystrVectors(t)
	bad := 0
	for _, item := range vectors.Floats {
		raw, err := strconv.ParseUint(item.Bits, 16, 64)
		if err != nil {
			t.Fatalf("bad bits %q: %v", item.Bits, err)
		}
		value := math.Float64frombits(raw)
		if got := pyFloatRepr(value); got != item.Str {
			bad++
			if bad <= 10 {
				t.Errorf("pyFloatRepr(%s) = %s, want %s", item.Bits, got, item.Str)
			}
		}
	}
	if bad > 10 {
		t.Errorf("%d float mismatches in total", bad)
	}
}

func TestPyNumberStrLiterals(t *testing.T) {
	for _, item := range loadPystrVectors(t).Numbers {
		if got := pyNumberStr(json.Number(item.Literal)); got != item.Str {
			t.Errorf("pyNumberStr(%s) = %s, want %s", item.Literal, got, item.Str)
		}
	}
}

func TestPyStrValues(t *testing.T) {
	for _, item := range loadPystrVectors(t).Values {
		value, err := decodeJSON([]byte(item.JSON))
		if err != nil {
			t.Fatalf("decode %s: %v", item.JSON, err)
		}
		if got := pyStr(value); got != item.Str {
			t.Errorf("pyStr(%s) = %s, want %s", item.JSON, got, item.Str)
		}
	}
}

// The exponent threshold is the rule Go's 'g' format gets wrong, so it is
// asserted here without reference to the generated vectors.
func TestPyFloatReprThreshold(t *testing.T) {
	cases := []struct {
		value float64
		want  string
	}{
		{1e15, "1000000000000000.0"},
		{1e16, "1e+16"},
		{1e-4, "0.0001"},
		{1e-5, "1e-05"},
		{100.0, "100.0"},
		{0.0, "0.0"},
		{math.Copysign(0, -1), "-0.0"},
		{1e21, "1e+21"},
		{5e-324, "5e-324"},
	}
	for _, item := range cases {
		if got := pyFloatRepr(item.value); got != item.want {
			t.Errorf("pyFloatRepr(%v) = %s, want %s", item.value, got, item.want)
		}
	}
}

// A null behavior is not a scored metric even when scoring_metrics contains the
// empty string. Before the fix the failed type assertion produced "", which is
// in that set, and C-05 passed where the reference fails.
func TestC05NonStringBehaviorIsNotScored(t *testing.T) {
	cases := []struct {
		behavior string
		detail   string
		ok       bool
	}{
		{`null`, `claim.behavior "None" is not among claim.scoring_metrics`, false},
		{`7`, `claim.behavior "7" is not among claim.scoring_metrics`, false},
		{`true`, `claim.behavior "True" is not among claim.scoring_metrics`, false},
		{`[1, "a"]`, `claim.behavior "[1, 'a']" is not among claim.scoring_metrics`, false},
		{`{"b": 1, "a": 2}`, `claim.behavior "{'b': 1, 'a': 2}" is not among claim.scoring_metrics`, false},
		{`""`, "", true},
	}
	for _, item := range cases {
		raw := `{"invariants":[{"property":"p","measurement":"m","metric":"x",` +
			`"direction":"floor","bound":0.1}],` +
			`"claim":{"behavior":` + item.behavior + `,"scoring_metrics":[""]}}`
		record, err := decodeJSON([]byte(raw))
		if err != nil {
			t.Fatalf("decode %s: %v", raw, err)
		}
		ok, detail := checkC05(record)
		if ok != item.ok {
			t.Errorf("behavior %s: ok = %v, want %v (detail %s)", item.behavior, ok, item.ok, detail)
		}
		if !item.ok && detail != item.detail {
			t.Errorf("behavior %s: detail = %s, want %s", item.behavior, detail, item.detail)
		}
	}
}
